<script lang="ts">
 import Badge from './FinancialBadge.svelte';import {defaultBaselineScope,type BaselineSetupModel,type BaselineSetupResult,type BaselineScope} from '$lib/baselineSetupTypes';
 let {model,commandKey,form,action='?/baselineSetup',loadAction=''}:{model:BaselineSetupModel;commandKey:string;form?:BaselineSetupResult|null;action?:string;loadAction?:string}=$props();
 const review=$derived(form?.ok&&form.phase==='review'?form.review:null);
 const missing=$derived(!model.accounts.length||model.accounts.some(a=>!a.offers.length)||!model.providerAvailable);
 const money=(n:number,currency:string)=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format(n/100);
 const scopeName=(scope:BaselineScope)=>({cash:'Budget cash',credit:'Budget credit card',tracking:'Tracking only'}[scope]);
</script>
<section class="product-panel baseline-setup" aria-labelledby="baseline-title">
 <header class="product-panel-header"><div><h2 id="baseline-title">Set your budget’s starting point</h2><p class="product-row-caption">Choose which accounts fund the budget, using balances from a completed day.</p></div><Badge label={model.phase==='active'?'Baseline saved':'One-time setup'} tone={model.phase==='active'?'positive':'movement'}/></header>
 <div class="baseline-body">
 {#if form&&!form.ok}<p class="baseline-error" role="alert">{form.error}</p>{/if}
 {#if model.phase==='active'&&model.active}
  <h3>Opening baseline is saved</h3><p>These are the accepted opening balances for the end of <strong>{model.active.date}</strong>, not today’s balances. This setup cannot replace or reset them.</p>
  {#each model.active.accounts as account(account.id)}<div class="baseline-account"><div><strong>{account.name}</strong><p class="product-row-caption">{scopeName(account.scope)} · opening balance</p></div><Badge value={money(account.balanceCents,model.active.currency)} label="Saved opening balance" tone={account.scope==='tracking'?'neutral':'movement'}/></div>{/each}
  <p class="product-attention">Refresh and verify posted activity after the cutoff before assigning money. Existing history and target plans stay intact.</p>
 {:else if review}
  <h3>Review before you start</h3><p>End of <strong>{review.date}</strong> in <strong>{review.timeZone}</strong> · {review.currency}. Earlier activity is already represented by these balances and must not be counted again.</p>
  {#each review.rows as row(row.id)}<article class="baseline-account"><div><h4>{row.name}</h4><p class="product-row-caption">{scopeName(row.scope)} · {row.evidence.source==='accepted_estimate'?'Accepted estimate':'Actual closing evidence'}</p><p class="baseline-evidence">{row.evidence.description}</p></div><Badge value={money(row.evidence.balanceCents,review.currency)} label="End-of-day balance" tone={row.scope==='tracking'?'neutral':'movement'}/></article>{/each}
  <div class="baseline-summary"><Badge value={money(review.cashCents,review.currency)} label="Opening budget cash" tone={review.cashCents<0?'negative':review.cashCents>0?'positive':'neutral'}/><Badge value={money(review.readyToAssignCents,review.currency)} label="Opening unassigned cash" tone={review.readyToAssignCents<0?'negative':'movement'}/></div>
  <p class="product-row-caption">Tracking balances do not fund spending. Card debt is not income; its payment reserve starts unfunded. Existing targets are plans, not assigned cash.</p>
  <form method="POST" {action} data-baseline-form="confirm">
   <input type="hidden" name="stage" value="activate"/><input type="hidden" name="date" value={review.date}/><input type="hidden" name="revision" value={review.revision}/><input type="hidden" name="roster" value={review.rosterFingerprint}/><input type="hidden" name="key" value={review.key}/><input type="hidden" name="review" value={review.fingerprint}/>
   {#each review.rows as row(row.id)}<input type="hidden" name={`scope_${row.id}`} value={row.scope}/><input type="hidden" name={`source_${row.id}`} value={row.evidence.reference}/>{/each}
   <label class="baseline-confirm"><input type="checkbox" name="confirm" value="end-of-day" required/><span>I have reviewed every account’s scope, evidence and end-of-day date. I understand this creates the opening baseline once and does not reset my existing records.</span></label>
   <div class="baseline-footer"><a class="product-button" href={`${loadAction||'?'}${loadAction.includes('?')?'&':loadAction?'?':''}baseline_date=${review.date}`}>Back to account setup</a><button class="product-button primary">Confirm opening baseline</button></div>
  </form>
 {:else}
  <p>Today’s balance is not proof of an earlier closing balance. Select a completed day and use approved evidence for every account, including tracking accounts.</p>
  <form method="GET" action={loadAction} class="baseline-date"><label>End-of-day date<input type="date" name="baseline_date" value={model.date} max={model.lastClosedDate} required/></label><button class="product-button">Load closing balances</button></form>
  <p class="product-row-caption">Closing timezone: {model.timeZone}. Only completed days through {model.lastClosedDate} are eligible.</p>
  {#if !model.providerAvailable}<p class="product-attention" role="status">Approved balance evidence is unavailable. A source must provide owner-matched closing balances for this date; no current balance will be relabeled as historical evidence.</p>{/if}
  <form method="POST" {action} data-baseline-form="review">
   <input type="hidden" name="stage" value="review"/><input type="hidden" name="date" value={model.date}/><input type="hidden" name="revision" value={model.revision}/><input type="hidden" name="roster" value={model.rosterFingerprint}/><input type="hidden" name="key" value={commandKey}/>
   {#each model.accounts as account(account.id)}<article class="baseline-choice"><h3>{account.name}</h3><p class="product-row-caption">Account type: {account.type}</p><div class="baseline-grid"><label>Budget role<select name={`scope_${account.id}`} required><option value="" disabled>Choose a role</option><option value="cash" selected={defaultBaselineScope(account.type)==='cash'}>Budget cash — available to assign</option><option value="credit" selected={defaultBaselineScope(account.type)==='credit'}>Budget credit card — debt and reserve</option><option value="tracking" selected={defaultBaselineScope(account.type)==='tracking'}>Tracking only — excluded from spendable cash</option></select></label><label>Closing-balance evidence<select name={`source_${account.id}`} required disabled={!account.offers.length}><option value="" selected={account.offers.length!==1} disabled>Choose approved evidence</option>{#each account.offers as offer(offer.reference)}<option value={offer.reference} selected={account.offers.length===1}>{money(offer.balanceCents,offer.currency)} · {offer.source==='accepted_estimate'?'Accepted estimate':'Actual'} · {offer.description}</option>{/each}</select></label></div><p class="product-row-caption">Role is suggested from the account type; change it only when this account is intentionally used differently.</p>{#if account.issue}<p class="baseline-warning">{account.issue}</p>{/if}</article>{/each}
   {#if !model.accounts.length}<p class="product-attention">No accounts are available to set up.</p>{/if}
   <p class="product-row-caption">Balances owed on credit cards are negative; positive credit balances are credits. All accounts must use one currency. No conversion, missing balance or funded category is invented.</p>
   <div class="baseline-footer"><span class="product-row-caption">Review first. Nothing is saved at this step.</span><button class="product-button primary" disabled={missing}>Review opening baseline</button></div>
  </form>
 {/if}
 </div>
</section>
<style>
 .baseline-setup>.product-panel-header{flex-wrap:wrap}.baseline-setup>.product-panel-header>div{flex:1 1 16rem;min-width:0}
 .baseline-setup h2,.baseline-setup h3,.baseline-setup h4{margin:0 0 8px}.baseline-body{padding:22px}.baseline-body p{line-height:1.55}.baseline-date{display:flex;align-items:end;gap:14px;margin:20px 0}.baseline-date label{flex:1}.baseline-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.baseline-grid label,.baseline-date label{display:flex;flex-direction:column;gap:8px;font-size:13px;font-weight:600;min-width:0}.baseline-grid select,.baseline-date input{min-height:46px;width:100%;box-sizing:border-box;background:var(--surface);color:var(--foreground);border:1px solid var(--input);border-radius:var(--radius);padding:10px 12px;font:inherit}.baseline-choice{padding:18px 0;border-bottom:1px solid var(--border)}.baseline-account{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:18px 0;border-bottom:1px solid var(--border)}.baseline-account>div{min-width:0}.baseline-evidence{font-size:13px;color:var(--muted-foreground);overflow-wrap:anywhere}.baseline-summary{display:flex;gap:14px;flex-wrap:wrap;margin:22px 0}.baseline-confirm{display:flex;align-items:flex-start;gap:12px;padding:18px 0;line-height:1.5}.baseline-confirm input{width:24px;height:24px;flex-shrink:0;margin:2px 0}.baseline-footer{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:22px 0 0}.baseline-footer button,.baseline-date button,.baseline-footer a{min-height:46px;flex-shrink:0}.baseline-footer button:disabled{opacity:.45;cursor:not-allowed}.baseline-error{background:var(--pill-negative-fill);color:var(--pill-negative-ink);padding:14px;border-radius:12px}.baseline-warning{color:var(--warning);font-size:13px}.baseline-setup :is(input,select,button,a):focus-visible{outline:3px solid var(--ring);outline-offset:3px}@media(max-width:600px){.baseline-body{padding:16px}.baseline-grid{grid-template-columns:1fr}.baseline-date,.baseline-footer,.baseline-account{flex-direction:column;align-items:stretch}.baseline-footer button,.baseline-date button{width:100%}.baseline-confirm{min-height:44px}}
</style>
